"""Order state-machine, order aggregates, builder, and log."""

from __future__ import annotations

from typing import Dict, FrozenSet, Iterator, List, Tuple

from .base import PricingStrategy
from .enums import OrderStatus
from .exceptions import DuplicateEntityError, InvalidTransitionError
from .models import Customer, LineItem, Money
from .pricing import FlatPricing


class OrderStateMachine:
    """Legal OrderStatus transitions, data-driven via TRANSITIONS."""

    TRANSITIONS: Dict[OrderStatus, FrozenSet[OrderStatus]] = {
        OrderStatus.NEW: frozenset({OrderStatus.RESERVED, OrderStatus.CANCELLED}),
        OrderStatus.RESERVED: frozenset({OrderStatus.SHIPPED, OrderStatus.CANCELLED}),
        OrderStatus.SHIPPED: frozenset(),
        OrderStatus.CANCELLED: frozenset(),
    }

    @staticmethod
    def allowed_from(status: OrderStatus) -> FrozenSet[OrderStatus]:
        """Return the set of statuses reachable from ``status``."""
        if not isinstance(status, OrderStatus):
            raise TypeError("status must be OrderStatus")
        return OrderStateMachine.TRANSITIONS[status]

    def can_transition(self, source: OrderStatus, target: OrderStatus) -> bool:
        """Return whether ``target`` is reachable from ``source``."""
        return target in OrderStateMachine.allowed_from(source)

    def transition(self, source: OrderStatus, target: OrderStatus) -> OrderStatus:
        pass

    def __call__(self, source: OrderStatus, target: OrderStatus) -> OrderStatus:
        """Convenience alias for :meth:`transition`."""
        return self.transition(source, target)

class Order:
    """Customer order with items, status, and pricing."""

    def __init__(self, order_id: str, customer: Customer, pricing: PricingStrategy) -> None:
        """Create a new order in the NEW status for ``customer``."""
        if not isinstance(order_id, str) or order_id.strip() == "":
            raise ValueError("order_id required")
        if not isinstance(customer, Customer):
            raise TypeError("customer must be Customer")
        if not isinstance(pricing, PricingStrategy):
            raise TypeError("pricing must be PricingStrategy")
        self._order_id = order_id
        self._customer = customer
        self._pricing = pricing
        self._items: List[LineItem] = []
        self._status: OrderStatus = OrderStatus.NEW
        self._machine = OrderStateMachine()

    @property
    def order_id(self) -> str:
        """Return the order identity."""
        return self._order_id

    @property
    def customer(self) -> Customer:
        """Return the owning customer."""
        return self._customer

    @property
    def status(self) -> OrderStatus:
        """Return the current order status."""
        return self._status

    @property
    def items(self) -> Tuple[LineItem, ...]:
        """Return a tuple copy of the order's line items."""
        return tuple(self._items)

    @property
    def total(self) -> Money:
        """Return the total price of all line items under this order's pricing."""
        return self._pricing.price(self._items)

    def add_item(self, item: LineItem) -> None:
        """Append ``item``, merging with an existing line for the same SKU."""
        if not isinstance(item, LineItem):
            raise TypeError("item must be LineItem")
        if self._status is not OrderStatus.NEW:
            raise InvalidTransitionError(self._status, OrderStatus.NEW)
        for index, existing in enumerate(self._items):
            if existing.sku == item.sku:
                self._items[index] = existing.with_quantity(existing.quantity + item.quantity)
                return
        self._items.append(item)

    def advance(self, target: OrderStatus) -> None:
        """Transition the order to ``target`` status, raising if not allowed."""
        new_status = self._machine.transition(self._status, target)
        self._status = new_status

    def __len__(self) -> int:
        pass

    def __iter__(self) -> Iterator[LineItem]:
        """Iterate over a tuple snapshot of the order's line items."""
        return iter(tuple(self._items))

    def __eq__(self, other: object) -> bool:
        """Compare orders by identity."""
        if not isinstance(other, Order):
            return NotImplemented
        return self._order_id == other._order_id

    def __hash__(self) -> int:
        """Hash by type name and order id."""
        return hash(("Order", self._order_id))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"Order({self._order_id!r}, {self._status.value})"

"""Unit tests for the orders module."""
from __future__ import annotations

import unittest

from playground.base import PricingStrategy
from playground.enums import OrderStatus
from playground.exceptions import DuplicateEntityError, InvalidTransitionError
from playground.models import Customer, LineItem, Money
from playground.orders import Order, OrderBuilder, OrderLog, OrderStateMachine
from playground.pricing import BulkDiscountPricing, FlatPricing


def _customer() -> Customer:
    return Customer("C-1", "Alice", Money(1000000))


def _order(order_id: str = "ORD-1", pricing: PricingStrategy | None = None) -> Order:
    return Order(order_id, _customer(), pricing or FlatPricing())


class OrderStateMachineTests(unittest.TestCase):
    def test_new_can_reach_reserved_and_cancelled(self) -> None:
        sm = OrderStateMachine()
        self.assertTrue(sm.can_transition(OrderStatus.NEW, OrderStatus.RESERVED))
        self.assertTrue(sm.can_transition(OrderStatus.NEW, OrderStatus.CANCELLED))

    def test_new_cannot_ship_directly(self) -> None:
        self.assertFalse(OrderStateMachine().can_transition(OrderStatus.NEW, OrderStatus.SHIPPED))

    def test_reserved_can_ship_or_cancel(self) -> None:
        sm = OrderStateMachine()
        self.assertTrue(sm.can_transition(OrderStatus.RESERVED, OrderStatus.SHIPPED))
        self.assertTrue(sm.can_transition(OrderStatus.RESERVED, OrderStatus.CANCELLED))

    def test_reserved_cannot_return_to_new(self) -> None:
        self.assertFalse(OrderStateMachine().can_transition(OrderStatus.RESERVED, OrderStatus.NEW))

    def test_terminal_states_have_no_outgoing(self) -> None:
        sm = OrderStateMachine()
        for source in (OrderStatus.SHIPPED, OrderStatus.CANCELLED):
            for target in OrderStatus:
                with self.subTest(source=source, target=target):
                    self.assertFalse(sm.can_transition(source, target))

    def test_allowed_from_returns_frozenset(self) -> None:
        allowed = OrderStateMachine.allowed_from(OrderStatus.NEW)
        self.assertIsInstance(allowed, frozenset)
        self.assertEqual(allowed, frozenset({OrderStatus.RESERVED, OrderStatus.CANCELLED}))

    def test_allowed_from_terminal_is_empty(self) -> None:
        self.assertEqual(OrderStateMachine.allowed_from(OrderStatus.SHIPPED), frozenset())

    def test_allowed_from_non_status_raises(self) -> None:
        with self.assertRaises(TypeError):
            OrderStateMachine.allowed_from("new")  # type: ignore[arg-type]

    def test_transition_returns_target_when_legal(self) -> None:
        sm = OrderStateMachine()
        self.assertIs(sm.transition(OrderStatus.NEW, OrderStatus.RESERVED), OrderStatus.RESERVED)

    def test_transition_illegal_raises(self) -> None:
        with self.assertRaises(InvalidTransitionError) as ctx:
            OrderStateMachine().transition(OrderStatus.NEW, OrderStatus.SHIPPED)
        self.assertIs(ctx.exception.source, OrderStatus.NEW)
        self.assertIs(ctx.exception.target, OrderStatus.SHIPPED)

    def test_call_is_alias_for_transition(self) -> None:
        sm = OrderStateMachine()
        self.assertIs(sm(OrderStatus.RESERVED, OrderStatus.SHIPPED), OrderStatus.SHIPPED)
        with self.assertRaises(InvalidTransitionError):
            sm(OrderStatus.SHIPPED, OrderStatus.NEW)


class OrderConstructionTests(unittest.TestCase):
    def test_initial_state(self) -> None:
        o = _order("ORD-9")
        self.assertEqual(o.order_id, "ORD-9")
        self.assertEqual(o.customer.customer_id, "C-1")
        self.assertIs(o.status, OrderStatus.NEW)
        self.assertEqual(o.items, ())
        self.assertEqual(len(o), 0)

    def test_empty_order_id_rejected(self) -> None:
        with self.assertRaises(ValueError):
            Order("  ", _customer(), FlatPricing())

    def test_non_str_order_id_rejected(self) -> None:
        with self.assertRaises(ValueError):
            Order(None, _customer(), FlatPricing())  # type: ignore[arg-type]

    def test_non_customer_rejected(self) -> None:
        with self.assertRaises(TypeError):
            Order("ORD-1", "alice", FlatPricing())  # type: ignore[arg-type]

    def test_non_pricing_rejected(self) -> None:
        with self.assertRaises(TypeError):
            Order("ORD-1", _customer(), lambda items: Money(0))  # type: ignore[arg-type]

    def test_customer_property(self) -> None:
        c = _customer()
        o = Order("ORD-1", c, FlatPricing())
        self.assertIs(o.customer, c)

"""Inventory ledger and warehouse location."""

from __future__ import annotations

from typing import Dict, Iterator

from .base import Entity, Repository
from .exceptions import InvalidTransitionError, OutOfStockError, UnknownSKUError
from .util import ensure_positive_int, normalize_sku


class InventoryLedger:
    """Tracks on-hand and reserved quantities per SKU."""

    def __init__(self, product_repo: Repository) -> None:
        """Create a ledger backed by ``product_repo`` for SKU validation."""
        if not isinstance(product_repo, Repository):
            raise TypeError("product_repo must be a Repository")
        self._product_repo = product_repo
        self._on_hand: Dict[str, int] = {}
        self._reserved: Dict[str, int] = {}

    def _require_sku(self, sku: str) -> str:
        """Normalise ``sku`` and raise ``UnknownSKUError`` if it is unregistered."""
        sku = normalize_sku(sku)
        if sku not in self._product_repo:
            raise UnknownSKUError(sku)
        return sku

    def add_stock(self, sku: str, quantity: int) -> int:
        """Add ``quantity`` to on-hand stock for ``sku``; return the new total."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        self._on_hand[sku] = self._on_hand.get(sku, 0) + quantity
        return self._on_hand[sku]

    def available(self, sku: str) -> int:
        """Return on-hand minus reserved for ``sku``."""
        sku = self._require_sku(sku)
        return self._on_hand.get(sku, 0) - self._reserved.get(sku, 0)

    def reserve(self, sku: str, quantity: int) -> ReservationContext:
        """Reserve ``quantity`` of ``sku`` and return a context that can commit or release it."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        avail = self.available(sku)
        if quantity > avail:
            raise OutOfStockError(sku, quantity, avail)
        self._reserved[sku] = self._reserved.get(sku, 0) + quantity
        return ReservationContext(self, sku, quantity)

    def release(self, sku: str, quantity: int) -> None:
        """Release ``quantity`` previously reserved for ``sku``."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        reserved = self._reserved.get(sku, 0)
        if quantity > reserved:
            raise InvalidTransitionError(reserved, quantity)
        self._reserved[sku] = reserved - quantity

    def commit(self, sku: str, quantity: int) -> None:
        """Commit ``quantity`` of ``sku``: decrement both reserved and on-hand."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        reserved = self._reserved.get(sku, 0)
        if quantity > reserved:
            raise InvalidTransitionError(reserved, quantity)
        self._reserved[sku] = reserved - quantity
        self._on_hand[sku] = self._on_hand.get(sku, 0) - quantity

    def __contains__(self, sku: object) -> bool:
        pass

    def __len__(self) -> int:
        """Return the number of SKUs with positive on-hand stock."""
        return sum(1 for qty in self._on_hand.values() if qty > 0)

    def __iter__(self) -> Iterator[str]:
        """Iterate over SKUs with positive on-hand stock, in sorted order."""
        for sku in sorted(k for k, v in self._on_hand.items() if v > 0):
            yield sku

