        self._sku = sku
        self._name = name
        self._category = category
        self._unit_price = unit_price

    @property
    def sku(self) -> str:
        """Return the product SKU."""
        return self._sku

    @property
    def name(self) -> str:
        """Return the product name."""
        return self._name

    @property
    def category(self) -> Category:
        """Return the product category."""
        return self._category

    @property
    def unit_price(self) -> Money:
        """Return the product unit price."""
        return self._unit_price

    def identity(self) -> str:
        """Return the SKU as the entity identity."""
        return self._sku

    def with_price(self, new_price: Money) -> Product:
        """Return a copy of this product with an updated unit price."""
        if not isinstance(new_price, Money):
            raise TypeError("new_price must be Money")
        return Product(self._sku, self._name, self._category, new_price)

    @classmethod
    def from_dict(cls, data: Mapping[str, object]) -> Product:
        """Build a product from a mapping with keys sku, name, category, unit_price_cents."""
        for key in ("sku", "name", "category", "unit_price_cents"):
            if key not in data:
                raise KeyError(key)
        raw_category = data["category"]
        if isinstance(raw_category, str):
            category = Category.from_label(raw_category)
        elif isinstance(raw_category, Category):
            category = raw_category
        else:
            raise TypeError("category must be str or Category")
        unit_price = Money(data["unit_price_cents"])
        return cls(data["sku"], data["name"], category, unit_price)

    @staticmethod
    def is_valid_name(name: str) -> bool:
        """Return True if ``name`` is a string of 1..80 non-blank characters."""
        if not isinstance(name, str):
            return False
        return 1 <= len(name.strip()) <= 80

"""Synchronous in-process event bus for the playground package."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Callable, Dict, List

from .enums import EventType


class EventBus:
    """Synchronous publish/subscribe keyed by :class:`EventType`."""

    def __init__(self) -> None:
        """Initialise an empty handler registry."""
        self._handlers: Dict[EventType, List[Callable[..., None]]] = {}

    def subscribe(self, event_type: EventType, handler: Callable[..., None]) -> None:
        """Register ``handler`` to be called when ``event_type`` is published."""
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not callable(handler):
            raise TypeError("handler must be callable")
        self._handlers.setdefault(event_type, []).append(handler)

    def unsubscribe(self, event_type: EventType, handler: Callable[..., None]) -> bool:
        """Remove ``handler`` from ``event_type``; return whether it was present."""
        handlers = self._handlers.get(event_type, [])
        if handler not in handlers:
            return False
        handlers.remove(handler)
        return True

    def publish(self, event_type: EventType, payload: Mapping[str, object]) -> int:
        """Invoke every handler subscribed to ``event_type`` with ``payload``.

        Returns the number of handlers invoked.
        """
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not isinstance(payload, Mapping):
            raise TypeError("payload must be a Mapping")
        count = 0
        for handler in list(self._handlers.get(event_type, [])):
            handler(payload)
            count += 1
        return count

    def __len__(self) -> int:
        """Return the total number of registered handlers across all event types."""
        return sum(len(handlers) for handlers in self._handlers.values())

    def __contains__(self, event_type: object) -> bool:
        pass

