class AuditTrailCallTests(unittest.TestCase):
    def test_non_callable_rejected(self) -> None:
        trail = AuditTrail()
        with self.assertRaises(TypeError):
            trail(42)  # type: ignore[arg-type]

    def test_success_records_ok_and_returns_result(self) -> None:
        trail = AuditTrail("audit")

        @trail
        def add(a: int, b: int) -> int:
            return a + b

        self.assertEqual(add(2, 3), 5)
        self.assertEqual(trail.entries, ("audit:add:ok",))

    def test_exception_records_error_and_reraises(self) -> None:
        trail = AuditTrail("audit")

        @trail
        def fail() -> None:
            raise ValueError("bad")

        with self.assertRaises(ValueError):
            fail()
        self.assertEqual(trail.entries, ("audit:fail:error:ValueError",))

    def test_error_type_name_reflects_exception_class(self) -> None:
        trail = AuditTrail("t")

        @trail
        def boom() -> None:
            raise KeyError("x")

        with self.assertRaises(KeyError):
            boom()
        self.assertEqual(trail.entries, ("t:boom:error:KeyError",))

    def test_wrapper_preserves_metadata(self) -> None:
        trail = AuditTrail()

        @trail
        def documented(x: int) -> int:
            """Doc string."""
            return x

        self.assertEqual(documented.__name__, "documented")
        self.assertEqual(documented.__doc__, "Doc string.")

    def test_passes_args_and_kwargs(self) -> None:
        trail = AuditTrail()

        @trail
        def f(a: int, *rest: int, key: str = "k") -> str:
            return f"{a}-{len(rest)}-{key}"

        self.assertEqual(f(1, 2, 3, key="z"), "1-2-z")

    def test_multiple_calls_accumulate_in_order(self) -> None:
        trail = AuditTrail("x")

        @trail
        def ok() -> None:
            return None

        @trail
        def bad() -> None:
            raise RuntimeError()

        ok()
        with self.assertRaises(RuntimeError):
            bad()
        ok()
        self.assertEqual(
            trail.entries,
            ("x:ok:ok", "x:bad:error:RuntimeError", "x:ok:ok"),
        )
        self.assertEqual(len(trail), 3)

    def test_same_trail_shared_between_functions(self) -> None:
        trail = AuditTrail("s")

        @trail
        def one() -> int:
            return 1

        @trail
        def two() -> int:
            return 2

        one()
        two()
        self.assertEqual(trail.entries, ("s:one:ok", "s:two:ok"))

    def test_base_exception_not_caught_but_not_recorded(self) -> None:
        trail = AuditTrail()

        @trail
        def interrupt() -> None:
            raise KeyboardInterrupt()

        with self.assertRaises(KeyboardInterrupt):
            interrupt()
        self.assertEqual(trail.entries, ())

"""Core domain models: money, products, line items, and customers."""

from __future__ import annotations

from typing import Mapping

from .base import Entity
from .enums import Category
from .util import ensure_positive_int, format_cents, normalize_sku


class Money:
    """Immutable integer-cents amount."""

    def __init__(self, cents: int = 0) -> None:
        """Create a monetary amount; cents must be a non-negative ``int``."""
        if isinstance(cents, bool) or not isinstance(cents, int):
            raise TypeError("cents must be int")
        if cents < 0:
            raise ValueError("money cannot be negative")
        self._cents = cents

    @property
    def cents(self) -> int:
        """Return the stored cents value."""
        return self._cents

    def __add__(self, other: Money) -> Money:
        """Return a new Money equal to ``self + other``."""
        if not isinstance(other, Money):
            raise TypeError("can only add Money to Money")
        return Money(self._cents + other._cents)

    def __sub__(self, other: Money) -> Money:
        """Return a new Money equal to ``self - other``.

        Raises:
            TypeError: if ``other`` is not :class:`Money`.
            ValueError: if the result would be negative.
        """
        if not isinstance(other, Money):
            raise TypeError("can only subtract Money from Money")
        difference = self._cents - other._cents
        if difference < 0:
            raise ValueError("subtraction would be negative")
        return Money(difference)

    def __mul__(self, factor: int) -> Money:
        """Return ``self`` multiplied by a non-negative integer."""
        if isinstance(factor, bool) or not isinstance(factor, int):
            raise TypeError("factor must be int")
        if factor < 0:
            raise ValueError("factor cannot be negative")
        return Money(self._cents * factor)

    def __rmul__(self, factor: int) -> Money:
        """Support ``factor * Money`` by delegating to :meth:`__mul__`."""
        return self.__mul__(factor)

    def __eq__(self, other: object) -> bool:
        """Return True if ``other`` is Money with equal cents."""
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents == other._cents

    def __lt__(self, other: Money) -> bool:
        """Return True if ``self`` is strictly less than ``other``."""
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents < other._cents

    def __le__(self, other: Money) -> bool:
        """Return True if ``self`` is less than or equal to ``other``."""
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents <= other._cents

    def __hash__(self) -> int:
        """Hash by the type name and cents value."""
        return hash(("Money", self._cents))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"Money({self._cents})"

    def __str__(self) -> str:
        """Render the amount as a ``$X.YY`` string."""
        return format_cents(self._cents)

    def __bool__(self) -> bool:
        pass

